# owner: platform
"""Seating charts: students sorted by last name and split into rows."""

from typing import List, Sequence

from rosterkit.models import Student


def _check_inputs(students: Sequence[Student], seats_per_row: int) -> None:
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    if not students:
        raise ValueError("no students to seat")


def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())


def _format_row(number: int, members: Sequence[Student]) -> str:
    names = " | ".join(member.display_name for member in members)
    return f"Row {number}: {names}"


# ---
def seating_rows(students: Sequence[Student], seats_per_row: int) -> List[str]:
    """One line of text per row, students ordered by last name."""
    _check_inputs(students, seats_per_row)
    ordered = sorted(students, key=_sort_key)
    chunks = [ordered[start:start + seats_per_row]
              for start in range(0, len(ordered), seats_per_row)]
    return [_format_row(number, chunk) for number, chunk in enumerate(chunks, 1)]

